#!/usr/bin/env python3
from pathlib import Path
import subprocess,sys,json,hashlib
R=Path(__file__).resolve().parents[2];T=Path(__file__).resolve().parent;O=Path(sys.argv[1])
subprocess.run([sys.executable,str(R/'tools/s1-native-prepared-field-current-stream-20261025/prepare.py'),str(O)],check=True)
p=O/'core-workspace/crates/aspis-core/src/r0_transcript.rs';original=p.read_text();p.write_text(original+(T/'wrapper.rs').read_text()+'\n#[cfg(kani)]mod s126_pairs_proofs{use super::*;\n'+(T/'proofs.rs').read_text()+'\n}\n')
manifest=O/'core-workspace/crates/aspis-core/Cargo.toml';before=manifest.read_text();assert before.count('\n[dev-dependencies]\n')==1
