(O/'core-workspace/Cargo.lock').write_text('# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\nversion = 4\n\n[[package]]\nname = "aspis-core"\nversion = "0.1.0"\n')
files={str(p.relative_to(O)):hashlib.sha256(p.read_bytes()).hexdigest()for p in O.rglob('*')if p.is_file()}
(O/'query-binding.json').write_text(json.dumps(dict(schema='focused-extractor-proof-packet-v1',files=files,freeze='4bb3b3f51e16b4525f1d10336e2b0bcbbd775387',domain='Native original queries_from_pairs andfinish/default execute. TWO scan cuts replay common full22-word/uSize/uSize/Bool states with postlen<=22/postdraws<=64. Exact per-call prestate/32-byteblock, accepted22-array/selected32-byte state or entire native QuerySampleError; universal observation call0..7/word0..21/byte0..31. No actual source caller/SDK/release closure.',remaining='Relative driver proof; actual scan callee law andcaller/runtime/release composition separate.'),indent=2)+'\n')
